  // Rotate the offset vector by the same rotation as the door to get the correct position of the door relative to the hinge.
  const rotatedOffsetVector = sinQuaternion.rotate(offsetVector);

  // Move the door to the correct position relative to the hinge, then rotate it around the hinge using the sinQuaternion.
  this.door?.moveRelativeTo(this.props.Hinge, rotatedOffsetVector, Space.World);
