class SparseMatrix:
    def __init__(self, numRows, numCols):
        self.numRows = numRows
        self.numCols = numCols
        self.entries = {}

    def get(self, row, col):
        return self.entries.get((row, col), 0)

    def put(self, row, col, value):
        if value != 0:
            self.entries[(row, col)] = value
        elif (row, col) in self.entries:
            del self.entries[(row, col)]

    def add(self, otherSparseMatrix):
        if self.numRows != otherSparseMatrix.numRows or self.numCols != otherSparseMatrix.numCols:
            raise ValueError("Cannot add two sparse matrices with different dimensions")
        for (row, col), value in otherSparseMatrix.entries.items():
            self.entries[(row, col)] = self.get(row, col) + value
```

