It is generally considered challenging to write a single cross-platform C++ code to retrieve the local network gateway IP using only the Standard Library (STL), as the STL does not inherently support networking functionalities. 

To accomplish this task, it is necessary to utilize platform-specific APIs to access network information on each operating system. On Linux and macOS, the `getifaddrs()` function is commonly used, while on Windows, the `GetAdaptersInfo()` function is typically employed.

Below is an example of how a C++ program might be structured to work on Linux, macOS, and Windows by using preprocessor directives to manage the platform-specific code. It is important to note that this code requires linking to the `iphlpapi.lib` library on Windows. This library is part of the Windows SDK and is not considered an external library.
```cpp
#include <iostream>
#include <string>

#if defined(_WIN32)
#include <winsock2.h>
#include <iphlpapi.h>
#pragma comment(lib, "iphlpapi.lib")

std::string get_gateway_ip() {
    std::string gateway_ip;
    IP_ADAPTER_INFO adapter_info[16];
    DWORD buf_len = sizeof(adapter_info);

    DWORD status = GetAdaptersInfo(adapter_info, &buf_len);
    if (status == ERROR_SUCCESS) {
        PIP_ADAPTER_INFO adapter = adapter_info;
        gateway_ip = adapter->GatewayList.IpAddress.String;
    }
    return gateway_ip;
}

#elif defined(__unix__) || defined(__APPLE__)
#include <sys/types.h>
#include <ifaddrs.h>
#include <netinet/in.h>
#include <arpa/inet.h>

std::string get_gateway_ip() {
    struct ifaddrs *ifaddr, *ifa;
    char gateway_ip[INET_ADDRSTRLEN] = {0};

    if (getifaddrs(&ifaddr) == -1) {
        perror("getifaddrs");
        return "";
    }

    for (ifa = ifaddr; ifa != nullptr; ifa = ifa->ifa_next) {
        if (ifa->ifa_addr == nullptr) {
            continue;
        }

        if ((ifa->ifa_flags & IFF_UP) && (ifa->ifa_flags & IFF_RUNNING) && !(ifa->ifa_flags & IFF_LOOPBACK)) {
            if (ifa->ifa_addr->sa_family == AF_INET) {
                void* tmp_addr_ptr = &((struct sockaddr_in *) ifa->ifa_addr)->sin_addr;
                inet_ntop(AF_INET, tmp_addr_ptr, gateway_ip, sizeof(gateway_ip));
                break;
            }
        }
    }
    freeifaddrs(ifaddr);
    return gateway_ip;
}

#endif

int main() {
