using System;
using System.Linq;
using System.Net;
using System.Net.NetworkInformation;

class Program {
    static void Main() {
        var host = Dns.GetHostEntry(Dns.GetHostName());
        var mostLikelyIp = host.AddressList.FirstOrDefault(ip => ip.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork && IPAddress.Parse(ip.ToString()).GetSubnetMask().ToString() == GetDefaultGateway().GetSubnetMask().ToString());
        Console.WriteLine("The most likely IP address of this computer is: " + mostLikelyIp);
    }

    public static IPAddress GetDefaultGateway()
    {
        return NetworkInterface
            .GetAllNetworkInterfaces()
            .Where(n => n.OperationalStatus == OperationalStatus.Up)
            .Where(n => n.NetworkInterfaceType != NetworkInterfaceType.Loopback)
            .SelectMany(n => n.GetIPProperties()?.GatewayAddresses)
            .Select(g => g?.Address)
            .Where(a => a != null)
            .FirstOrDefault();
    }
}
