public class OpportunityReportController {
  public List<OpportunityWithProducts> getOpportunitiesWithProducts() {
    // Query data based on the "Opportunities with Products" report type
    List<OpportunityWithProducts> opportunitiesWithProducts = [SELECT Id, Name, (SELECT Id, Name, Quantity, Price FROM OpportunityLineItems) FROM Opportunity];

    // Loop through the data and calculate the total value of all products for each opportunity
    for (OpportunityWithProducts opportunity : opportunitiesWithProducts) {
      Decimal totalProductValue = 0;
      for (OpportunityLineItem lineItem : opportunity.OpportunityLineItems) {
