import com.example.protobuf.Message1;
import com.example.protobuf.Message2;

public class ProtoDeserializer {

    public static void main(String[] args) throws InvalidProtocolBufferException {
        byte[] byteArray = // your protobuf byte array

        // Attempt to deserialize the byte array into Message1
        try {
            Message1 message1 = Message1.parseFrom(byteArray);
            // do something with message1
            System.out.println("Successfully deserialized byte array into Message1.");
        } catch (InvalidProtocolBufferException e1) {
            // If deserialization into Message1 fails, attempt to deserialize into Message2
            try {
                Message2 message2 = Message2.parseFrom(byteArray);
                // do something with message2
                System.out.println("Successfully deserialized byte array into Message2.");
            } catch (InvalidProtocolBufferException e2) {
                System.out.println("Failed to deserialize byte array into either Message1 or Message2.");
            }
        }
    }
}
