```c++
#include <iostream>

using namespace std;

// Define the node structure
struct Node {
    int data;
    Node* next;
};

// Function to add a new node to the linked list
void addNode(Node*& head, int data) {
    Node* newNode = new Node;
    newNode->data = data;
    newNode->next = nullptr;

    if (head == nullptr) {
        head = newNode;
    } else {
        Node* curr = head;
        while (curr->next != nullptr) {
            curr = curr->next;
        }
        curr->next = newNode;
    }
}

// Function to print the contents of the linked list
void printList(Node* head) {
    Node* curr = head;
    while (curr != nullptr) {
        cout << curr->data << " ";
        curr = curr->next;
    }
    cout << endl;
}

// Main function
int main() {
    Node* head = nullptr;

    // Add nodes to the list
    addNode(head, 5);
    addNode(head, 10);
    addNode(head, 15);
    addNode(head, 20);

    // Print the list
    printList(head);

    return 0;
}
```

This code demonstrates how to create a linked list of integers in C++. The `Node` struct defines each node's structure, including an integer `data` field and a pointer to the next node, `next`. The `addNode` function is designed to take a pointer to the head of the list, create a new node with the specified data, and append it to the end of the list. The `printList` function is used to output the contents of each node in the list. In the `main` function, an empty list is initialized, nodes are added, and the list's contents are printed.

