def load_data():
    bookings = {}  # Replace with actual bookings data
    lanes = {}  # Replace with actual lanes data
    staff = {}  # Replace with actual staff data
    return bookings, lanes, staff

def allocate_resources(bookings, lanes, staff):
    arrivals = [(b.return_date, b.booking_id) for b in bookings.values()]
    heapq.heapify(arrivals)

    while arrivals:
        _, booking_id = heapq.heappop(arrivals)
        booking = bookings[booking_id]

        assigned_staff = find_available_staff(staff)
        optimal_lane = find_optimal_lane(lanes)

        if assigned_staff and optimal_lane:
            assign_staff_to_booking(assigned_staff, booking)
            assign_lane_to_booking(optimal_lane, booking)

def find_available_staff(staff):
    for s in staff.values():
        if s.availability:
            return s
    return None

def find_optimal_lane(lanes):
    for l in lanes.values():
        if l.availability:
            return l
    return None

def assign_staff_to_booking(staff, booking):
    staff.availability = False
    booking.staff_id = staff.staff_id

def assign_lane_to_booking(lane, booking):
    lane.availability = False
    booking.lane_id = lane.lane_id

def main():
    bookings, lanes, staff = load_data()
    allocate_resources(bookings, lanes, staff)

if __name__ == "__main__":
