    static void InsertInBulk(List<string> zeroByteFiles, SqlConnection connection)
    {
        using (SqlCommand command = new SqlCommand("INSERT INTO ZeroByteFiles (FilePath) VALUES (@FilePath)", connection))
        {
            command.Parameters.Add("@FilePath", System.Data.SqlDbType.NVarChar);
            foreach (string file in zeroByteFiles)
            {
                command.Parameters["@FilePath"].Value = file;
                command.ExecuteNonQuery();
            }
        }
    }
}
```

In this example, the `rootDirectory` variable is set to the directory that you want to start traversing at. The `connectionString` variable is set to the connection string of the SQL Server database where you want to write the list of zero-byte files. The `TraverseDirectory` method is called recursively to traverse the directory tree, and the `Directory.EnumerateFiles` and `Directory.EnumerateDirectories` methods are used to get the files and subdirectories of the current directory. If the file length is 0, the full file path is added to the `zeroByteFiles` list. After all the subdirectories have been traversed, the `InsertInBulk` method is called to insert all the files in the list to the `ZeroByteFiles` table in the `ExternalData` database using SqlCommand and SqlParameter.

