```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.IO;
using System.Collections.Generic;

class Program
{
    static void Main(string[] args)
    {
        string rootDirectory = @"C:\example";
        string connectionString = "Server=localhost;Database=ExternalData;Trusted_Connection=True;";
        List<string> zeroByteFiles = new List<string>();
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();
            TraverseDirectory(rootDirectory, zeroByteFiles);
            InsertInBulk(zeroByteFiles, connection);
            connection.Close();
        }
    }
    static void TraverseDirectory(string directory, List<string> zeroByteFiles)
    {
        foreach (string file in Directory.EnumerateFiles(directory))
        {
            FileInfo fileInfo = new FileInfo(file);
            if (fileInfo.Length == 0)
            {
                zeroByteFiles.Add(fileInfo.FullName);
            }
        }

        foreach (string subdirectory in Directory.EnumerateDirectories(directory))
        {
            TraverseDirectory(subdirectory, zeroByteFiles);
        }
    }
    static void InsertInBulk(List<string> zeroByteFiles, SqlConnection connection)
    {
        DataTable zeroByteFilesTable = new DataTable();
        zeroByteFilesTable.Columns.Add("FilePath", typeof(string));
        foreach (string file in zeroByteFiles)
        {
            zeroByteFilesTable.Rows.Add(file);
        }

        using (SqlBulkCopy bulkCopy = new SqlBulkCopy(connection))
        {
            bulkCopy.DestinationTableName = "ZeroByteFiles";
            bulkCopy.WriteToServer(zeroByteFilesTable);
        }
    }
}
```

