function countWords(string) {
  // Use a regular expression to split the string into an array of words
  // The regular expression will match any sequence of one or more non-whitespace characters,
  // followed by any number of whitespace characters
  const words = string.split(/\S+\s*/);

  // Return the length of the array
  return words.length;
}
