    public List<SMTReportResponse> getSMTReport(SMTReportRequest request) {
        String sql = "SELECT * FROM msprw.smtaudit WHERE ";
        List<Object> params = new ArrayList<>();

        if (request.getStartDate() != null) {
            sql += "CREATE_TS >= ? ";
            params.add(request.getStartDate());
        }

        if (request.getEndDate() != null) {
            if (!params.isEmpty()) {
                sql += "AND ";
            }
            sql += "CREATE_TS <= ? ";
            params.add(request.getEndDate());
        }

        if (request.getOperationType() != null) {
            if (!params.isEmpty()) {
                sql += "AND ";
            }
            sql += "OPERATION_NAME = ? ";
            params.add(request.getOperationType());
        }

        return jdbcTemplate.query(sql, params.toArray(), new SMTReportResponseMapper());
    }

    private static class SMTReportResponseMapper implements RowMapper<SMTReportResponse> {
        @Override
        public SMTReportResponse mapRow(ResultSet rs, int rowNum) throws SQLException {
            SMTReportResponse response = new SMTReportResponse();
