以下是加入信号量机制的代码示例：

```c
#include <iostream>
#include <fstream>
#include <cstring>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <cstdlib>
#include <semaphore.h>
#include <fcntl.h>

#define BUF_SIZE 1024

int main(int argc, char *argv[]) {
    int sockfd;
    struct sockaddr_in addr;
    char buffer[BUF_SIZE];
    int len, ret;

    // 创建信号量
    sem_t *sem = sem_open("/my_sem", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("sem_open()");
        exit(EXIT_FAILURE);
    }

    // 创建套接字
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("socket()");
        exit(EXIT_FAILURE);
    }

    // 设置套接字地址和端口号
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(1234);
    addr.sin_addr.s_addr = htonl(INADDR_ANY);

    // 绑定套接字
    if (bind(sockfd, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
        perror("bind()");
        exit(EXIT_FAILURE);
    }

    // 创建子进程
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork()");
        exit(EXIT_FAILURE);
    }

    // 在父进程中，记录接收到的消息
    if (pid > 0) {
        while (1) {
            memset(buffer, 0, BUF_SIZE);
            len = recvfrom(sockfd, buffer, BUF_SIZE, 0, NULL, NULL);
            if (len == -1) {
                perror("recvfrom()");
                exit(EXIT_FAILURE);
            }

            // 获取信号量
            sem_wait(sem);

            // 记录接收到的消息
            std::ofstream log_file("parent.log", std::ios_base::app);
            if (!log_file) {
                perror("ofstream()");
                exit(EXIT_FAILURE);
            }
            log_file << "Received message: " << buffer << std::endl;
            log_file.close();

            // 释放信号量
            sem_post(sem);
        }
    }
    // 在子进程中，记录消息并将其发送回客户端
    else {
        while (1) {
            memset(buffer, 0, BUF_SIZE);
            len = recvfrom(sockfd, buffer, BUF_SIZE, 0, NULL, NULL);
            if (len == -1) {
                perror("recvfrom()");
                exit(EXIT_FAILURE);
            }

            // 获取信号量
            sem_wait(sem);

            // 记录接收到的消息
            std::ofstream log_file("child.log", std::ios_base::app);
            if (!log_file) {
                perror("ofstream()");
                exit(EXIT_FAILURE);
