// Create a function to connect to the websocket server
void ConnectToWebSocket()
{
    // Create a websocket URL
    const FString WebSocketUrl = TEXT("ws://localhost:8080");

    // Get the websockets module
    FWebSocketsModule& WebSockets = FWebSocketsModule::Get();

    // Connect to the websocket server
    WebSocket = WebSockets.CreateWebSocket(WebSocketUrl);
    if (WebSocket.IsValid())
    {
        WebSocket->OnConnected().AddLambda([]()
        {
            UE_LOG(LogTemp, Warning, TEXT("Connected to websocket server"));
            // Do something when the connection is established
        });

        WebSocket->OnConnectionError().AddLambda([](const FString& Error)
        {
            UE_LOG(LogTemp, Error, TEXT("WebSocket connection error: %s"), *Error);
            // Handle the error as needed
        });

        WebSocket->OnClosed().AddLambda([](int32 StatusCode, const FString& Reason, bool bWasClean)
        {
            UE_LOG(LogTemp, Warning, TEXT("WebSocket connection closed: %d %s"), StatusCode, *Reason);
            // Do something when the connection is closed
        });

        WebSocket->OnMessage().AddLambda([](const FString& Message)
        {
            HandleMessage(Message);
        });

        WebSocket->Connect();
    }
}

// Create a function to send a message to the websocket server
void SendMessageToWebSocket(const FString& Message)
{
    if (WebSocket.IsValid() && WebSocket->IsConnected())
    {
        WebSocket->Send(Message);
    }
}
```

