Here is an example of how server code can be modified to send an ACK packet in response to a client's request:

```c
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

int main(int argc, char *argv[])
{
    int socket_desc, client_sock, c, read_size;
    struct sockaddr_in server, client;
    char client_message[2000];
    char *ack_message = "ACK";

    //Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1)
    {
        printf("Could not create socket");
    }
    printf("Socket created\n");

    //Prepare the sockaddr_in structure
    server.sin_family = AF_INET;
    server.sin_addr.s_addr = INADDR_ANY;
    server.sin_port = htons(8888);

    //Bind
    if (bind(socket_desc, (struct sockaddr *)&server, sizeof(server)) < 0)
    {
        //print the error message
        perror("bind failed. Error");
        return 1;
    }
    printf("bind done\n");

    //Listen
    listen(socket_desc, 3);

    //Accept and incoming connection
    printf("Waiting for incoming connections...\n");
    c = sizeof(struct sockaddr_in);
    while ((client_sock = accept(socket_desc, (struct sockaddr *)&client, (socklen_t *)&c)))
    {
        printf("Connection accepted\n");

        //Receive a message from client
        while ((read_size = recv(client_sock, client_message, 2000, 0)) > 0)
        {
            //Process the message
            printf("Received message: %s\n", client_message);

            //Send an ACK in response
            if (send(client_sock, ack_message, strlen(ack_message), 0) < 0)
            {
                printf("Error sending ACK message");
            }
        }

        if (read_size == 0)
        {
            printf("Client disconnected\n");
        }
        else if (read_size == -1)
        {
            perror("recv failed");
        }
    }

    return 0;
}
```

In this example, a new variable `ack_message` is introduced, containing the string "ACK". After a message is received from the client, the code checks for successful reception and processes the message. An ACK message is then sent back to the client using the `send()` function. If there is an error in sending the ACK message, an error message is printed. It is noted that while this example uses a simple string for the ACK message, in practical applications, some developers might prefer to define a custom protocol with specific codes for different message types.

