```c
#include <iostream>
#include <stack>
#include <string>

using namespace std;

int countOccurrences(string str, string word) {
    int count = 0;
    stack<char> s;
    int len = str.length();
    int wordLen = word.length();
    for (int i = 0; i < len; i++) {
        s.push(str[i]);
        if (s.size() > wordLen) {
            s.pop();
        }
        if (s.size() == wordLen && s.top() == word[0]) {
            string temp = "";
            for (int j = 0; j < wordLen; j++) {
                temp += s.top();
                s.pop();
            }
            reverse(temp.begin(), temp.end());
            if (temp == word) {
                count++;
            } else {
                for (int j = 0; j < wordLen; j++) {
                    s.push(temp[j]);
                }
            }
        }
    }
    return count;
}

int main() {
    string str = "the quick brown fox jumps over the lazy dog";
    string word = "the";
    int count = countOccurrences(str, word);
    cout << "The word \"" << word << "\" occurs " << count << " times in the string." << endl;
    return 0;
}
```

In this example, a stack is used to track the most recent characters of the input string. Each character is pushed onto the stack, and if the stack size exceeds the length of the target word, the oldest character is removed.

When the stack size matches the length of the target word and the top character of the stack matches the first character of the target word, the top `wordLen` characters of the stack are compared with the target word. If they match, the `count` variable is incremented. If they do not match, the characters are pushed back onto the stack.

This implementation assumes that the input string and target word contain only lowercase letters. If the input string or target word includes uppercase letters, digits, or other characters, adjustments may be necessary.

